      hu: [],
      ro: [],
      en: [],
      es: ["Estructura original de madera construida en 1578", "Reemplazada por un edificio de piedra en 1679", "La torre octogonal mide 47 metros de altura", "Demolido completamente por las autoridades soviéticas en 1957", "Reconstrucción históricamente exacta completada en 2008", "Cuenta con un trompetero mecánico llamado Magislav", "Alberga el Museo de la Historia de Mahilyou"],
      pt: ["Estrutura original de madeira construída em 1578", "Substituída por um edifício de pedra em 1679", "A torre octogonal tem 47 metros de altura", "Completamente demolido pelas autoridades soviéticas em 1957", "Reconstrução historicamente precisa concluída em 2008", "Apresenta um trompetista mecânico chamado Magislav", "Alberga o Museu da História de Mahilyou"],
      fr: ["Structure originale en bois construite en 1578", "Remplacée par un bâtiment en pierre en 1679", "La tour octogonale mesure 47 mètres de haut", "Complètement démoli par les autorités soviétiques en 1957", "Reconstruction historiquement fidèle achevée en 2008", "Comprend un trompettiste mécanique nommé Magislav", "Abrite le musée de l'histoire de Mahilyou"],
